begin;
select plan(32);
insert into public.profiles(id) values('16100000-0000-0000-0000-000000000001'),('16100000-0000-0000-0000-000000000002');
set local role authenticated;
set local request.jwt.claim.sub='16100000-0000-0000-0000-000000000001';
select throws_ok($$select public.testing_report_submit('16100000-0000-0000-0000-000000000010','master','Informe','Texto',false)$$,'22023',null,'consent required');
select lives_ok($$select public.testing_report_submit('16100000-0000-0000-0000-000000000010','master','Informe','Texto',true)$$,'non tester can submit');
select lives_ok($$select public.testing_report_submit('16100000-0000-0000-0000-000000000010','master','Informe','Texto',true)$$,'retry does not duplicate');
select is((select count(*)::integer from public.testing_contributions),1,'one private row');
select throws_ok($$select public.testing_report_submit('16100000-0000-0000-0000-000000000010','master','Otro','Texto',true)$$,'23505',null,'different retry rejected');
select is(jsonb_array_length(public.testing_participation_current_v2('master')->'contributions'),1,'own history');
select lives_ok($$select public.testing_report_credit('16100000-0000-0000-0000-000000000010',true)$$,'credit opt in');
select is((public.testing_participation_current_v2('master')->'contributions'->0->>'credit')::boolean,true,'credit persisted');
set local request.jwt.claim.sub='16100000-0000-0000-0000-000000000002';
select is(jsonb_array_length(public.testing_participation_current_v2('master')->'contributions'),0,'other account sees no history');
select throws_ok($$select public.testing_report_credit('16100000-0000-0000-0000-000000000010',false)$$,'42501',null,'cannot change another credit');
select throws_ok($$select public.testing_report_fixed('16100000-0000-0000-0000-000000000010','1.2.3','Revisado','Resumen')$$,'42501',null,'user cannot mark fixed');
reset role;
insert into public.testing_center_memberships(user_id,actor_id,role) values('16100000-0000-0000-0000-000000000002','owner-1610','owner');
update public.testing_contributions set state='accepted';
set local role authenticated;
select lives_ok($$select public.testing_report_fixed('16100000-0000-0000-0000-000000000010','1.2.3','Revisado','Resumen')$$,'owner marks accepted report fixed');
select is(public.testing_report_patch_candidates('1.2.3')->0->>'summary','Resumen','patch candidate uses reviewed summary');
select ok(not ((public.testing_report_patch_candidates('1.2.3')->0) ? 'account_id'),'patch candidate omits identity');
select is(jsonb_array_length(public.testing_report_patch_candidates('1.2.4')),0,'other version has no candidates');
set local request.jwt.claim.sub='16100000-0000-0000-0000-000000000001';
select throws_ok($$select public.testing_report_patch_candidates('1.2.3')$$,'42501',null,'ordinary user cannot list patch candidates');
select is(public.testing_participation_current_v2('master')->'contributions'->0->>'state','fixed','real fixed state');
select is((public.testing_participation_current_v2('master')->'contributions'->0->>'notice')::boolean,true,'durable fixed notice');
select public.testing_report_notice_read('16100000-0000-0000-0000-000000000010','2000-01-01Z');
select is((public.testing_participation_current_v2('master')->'contributions'->0->>'notice')::boolean,true,'stale acknowledgement cannot hide change');
select public.testing_report_notice_read('16100000-0000-0000-0000-000000000010',(public.testing_participation_current_v2('master')->'contributions'->0->>'updated_at')::timestamptz);
select is((public.testing_participation_current_v2('master')->'contributions'->0->>'notice')::boolean,false,'acknowledgement persists');
select public.testing_report_credit('16100000-0000-0000-0000-000000000010',false);
select is((public.testing_participation_current_v2('master')->'contributions'->0->>'credit')::boolean,false,'credit revoked');
select throws_ok($$insert into public.testing_contributions(account_id,channel,title,body) values(auth.uid(),'master','Bypass','Body')$$,'42501',null,'no direct insert bypass');
select ok(not has_function_privilege('anon','public.testing_report_submit(uuid,text,text,text,boolean)','execute'),'anon cannot submit');
select ok(not has_function_privilege('authenticated','public.testing_contribution_submit(uuid,text,text,text)','execute'),'legacy RPC cannot bypass consent');
select ok(not has_table_privilege('authenticated','public.testing_report_followup','update'),'no direct credit bypass');
select lives_ok($$select public.testing_report_submit('16100000-0000-0000-0000-000000000020','master','Dos','Texto',true);
 select public.testing_report_submit('16100000-0000-0000-0000-000000000021','master','Tres','Texto',true);
 select public.testing_report_submit('16100000-0000-0000-0000-000000000022','master','Cuatro','Texto',true);
 select public.testing_report_submit('16100000-0000-0000-0000-000000000023','master','Cinco','Texto',true)$$,'five daily reports allowed');
select throws_ok($$select public.testing_report_submit('16100000-0000-0000-0000-000000000024','master','Seis','Texto',true)$$,'54000',null,'sixth daily report denied');
select lives_ok($$select public.testing_report_submit('16100000-0000-0000-0000-000000000010','master','Informe','Texto',true)$$,'retry still allowed at quota');
select is((select count(*)::integer from public.testing_contributions),5,'quota rejection preserves history');
reset role;
insert into public.profiles(id) values('16100000-0000-0000-0000-000000000003');
-- Supervisor seeds synthetic historical rows, never an API/user capability.
do $$declare item uuid; begin for i in 1..20 loop
 item:=gen_random_uuid();
 insert into public.testing_contributions(id,account_id,channel,title,body)
 values(item,'16100000-0000-0000-0000-000000000003','master','Weekly','Synthetic');
 update public.testing_contributions set created_at=clock_timestamp()-interval '2 days' where id=item;
end loop; end$$;
set local role authenticated;
set local request.jwt.claim.sub='16100000-0000-0000-0000-000000000003';
select is((select count(*)::integer from public.testing_contributions),20,'twenty weekly reports present');
select throws_ok($$select public.testing_report_submit('16100000-0000-0000-0000-000000000025','master','Weekly overflow','Texto',true)$$,'54000',null,'twenty first weekly report denied');
select is(jsonb_array_length(public.testing_participation_current_v2('master')->'contributions'),20,'history remains bounded');
select * from finish();
rollback;
